INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1057, 'koKR', 'Odzyskanie Zwęglonej Doliny', 'Jestem opiekunem duchów lasu, więc z pewnością domyślasz się, czemu jestem zaniepokojony.$b$b$GPrzemierzyłeś:Przemierzyłaś; te góry, by dotrzeć na ten szczyt. Na pewno $gwidziałeś:widziałaś; hańbę, jaka spotkała tę ziemię. Chciwość doprowadziła do zniszczenia tych świętych wzgórz.$b$bZwęgloną Dolinę na południu podpaliła chciwa, zmechanizowana armia przemysłowców. Co gorsza, harpie Krwawej Furii, które wdarły się na te ziemie, nie pozwalają nam przejść i rozpocząć odnowy lasu.$b$bPrzepędź te nędzne harpie, $n!', 'Opiekun Albagorm na Szczycie Szponogłazów chce, żebyś $gzabił:zabiła; 7 harpii Krwawej Furii, 7 napastniczek Krwawej Furii, 7 zabójczyń Krwawej Furii i 7 łotrzyc Krwawej Furii.', '', 'Wróć do opiekuna Albagorma na Szczycie Szponogłazów w Górach Szponogłazach.', '', '', '', '', 0),
(1058, 'koKR', 'Leśna magia Jin\'Zila', 'Jakże podekscytowany ja jestem!$b$bTrzy małe klatki dla trzech małych elfów! Ale co zrobimy z naszymi uroczymi przyjaciółmi, co to drzewa przytulają? Ano, dajmy im posmakować... jak oni to nazywają... leśnej magii!$b$bPotrzebuję porządnej porcji żywicy ze Szponogłazów. Od tych okropnych kotów przynieś mi wąsy zmierzchowych biegaczy. Do tego trzeba mnóstwa oczu biegaczy, rzecz jasna – oczu nigdy za wiele. Aha, i nie zapominajmy o cennej łusce baśniowego smoka.$b$bPędź na Szczyt Szponogłazów, $n, żebym mógł uwarzyć trochę leśnej magii!', 'Znachor Jin\'Zil w Malaka\'jin chce, żebyś $gprzyniósł:przyniosła; mu 5 porcji żywicy ze Szponogłazów, 5 wąsów zmierzchowego biegacza, 30 oczu biegacza i łuskę baśniowego smoka.', '', 'Wróć do znachora Jin\'Zila w Malaka\'jin w Górach Szponogłazach.', '', '', '', '', 0),
(1059, 'koKR', 'Odzyskanie Zwęglonej Doliny', 'Harpie Krwawej Furii zostały poskromione. Ale jeśli nic nie zrobimy, szybko się przegrupują.$b$bDaleko na południe od Pustkowi leży kraina zwana Tysiącem Filarów. Jeśli w Tysiącu Filarów wyruszysz na zachód, aż dotrzesz do bujnego skraju lasów Feralas, znajdziesz druida imieniem Falfindel Strażnik Szlaków.$b$bTen wielki i mądry druid potrafi przywołać potężne duchy lasu, które mogą pomóc w odzyskaniu Zwęglonej Doliny.$b$bPrzekaż mu wieść o naszej potrzebie! Odszukaj go natychmiast!', 'Udaj się do Falfindela Strażnika Szlaków na granicy Tysiąca Filarów i Feralas.', '', '', '', '', '', '', 0),
(1071, 'koKR', 'Wytchnienie dla gnoma', 'Widzisz, $N, jestem członkiem Oświeconego Zgromadzenia Nauk Arkanologicznych, Alchemicznych i Inżynieryjnych, a moim celem... nie, moim OBOWIĄZKIEM! jest pokazać nocnym elfom, że połączenie magii, mikstur i mechanizmów może pomóc ocalić ich lasy.$B$BAle to zażarta wojna, a gobliny, zdaje się, mnożą się jak króliki. Nie mam nawet czasu, żeby zbudować swoje najnowsze wynalazki!$B$BPotrzebuję trochę czasu, żeby wszystko zaplanować i zorganizować. Ale do tego potrzebuję twojej pomocy w powstrzymywaniu goblinów na Turni Tnącego Wiatru na wschodzie...', 'Zabij 10 drwali spółki Gitgeszeft i 10 karczowników spółki Gitgeszeft, a następnie wróć do Gaxima Rdzawosyka w Górach Szponogłazach.', '', 'Wróć do Gaxima Rdzawosyka na Ścieżce Sieciowijów w Górach Szponogłazach.', '', '', '', '', 0),
(1079, 'koKR', 'Tajna operacja – Alfa', 'To jest to, $N. Słuchaj uważnie. Urządzenia są gotowe do użycia.$B$BWeź te kartki – wyjaśnią ci więcej o detonatorach i materiałach wybuchowych oraz o tym, gdzie je umieścić.$B$BPamiętaj, powodzenie twojej misji nie zależy od tego, ile zniszczeń narobisz. Sukces planu Alfa zależy od tego, czy przyniesiesz plany inżynieryjne spółki Gitgeszeft z tartaku na południe od Jeziora Skalnej Sadzawki.', 'Zdobądź plany inżynieryjne spółki Gitgeszeft z tartaku na Turni Tnącego Wiatru.', '', 'Wróć do Gaxima Rdzawosyka na Ścieżce Sieciowijów w Górach Szponogłazach.', '', '', '', '', 0),
(1080, 'koKR', 'Tajna operacja – Beta', 'Plan Beta jest taki sam jak plan Alfa, $N.$B$BRobimy zamieszanie, a potem kradniemy ich cenne listy.$B$BNajważniejsze to zdobyć listy... zapamiętaj to.$B$BKartki, które ci już dałem, powiedzą ci, gdzie podłożyć ładunki. Po prostu wróć tu $gżywy:żywa; i z tymi listami...', 'Zdobądź listy spółki Gitgeszeft z Kopalni Tnącego Wiatru na wschodnim krańcu Turni Tnącego Wiatru.', '', 'Wróć do Gaxima Rdzawosyka na Ścieżce Sieciowijów w Górach Szponogłazach.', '', '', '', '', 0),
(1083, 'koKR', 'Rozwścieczone duchy', 'Nie wiem, co spółka Gitgeszeft zrobiła Dolinie, ale to oczywiste, że tamtejsze istoty okazały się od niej silniejsze.$B$BPodpalili las i użyli swoich niszczycielskich wynalazków, by obrócić w ruinę jak największą część Doliny.$B$BAle w swojej ignorancji uwolnili też coś jeszcze: płonące duchy, żywiołaki ognia, kamienia i gniewu.$B$BTa ziemia nie ujrzy uśmiechu Eluny, dopóki te istoty swobodnie po niej krążą.$B$BPrzynieś mi ich tlące się żarzewie na dowód, że $gprzetrzebiłeś:przetrzebiłaś; ich szeregi.', 'Przynieś Kaeli Cienistej Włóczni w Górach Szponogłazach 8 porcji tlącego się żarzewia, zdobytych na dowolnych żywiołakach ognia w Zwęglonej Dolinie.', '', 'Wróć do Kaeli Cienistej Włóczni na Ścieżce Sieciowijów w Górach Szponogłazach.', '', '', '', '', 0),
(1084, 'koKR', 'Zranione pradrzewce', 'Wydaje mi się oczywiste, że obrońcy Doliny – drzewce – mieli coś wspólnego z wyparciem spółki Gitgeszeft. Niestety, nawet ci niegdyś wielcy strażnicy ulegli teraz zepsuciu.$B$BGaxim uważa, że ich zepsucie ma jakiś związek z bronią, której gobliny użyły podczas odwrotu.$B$BPowiedziałam mu, że zdobędę próbkę od rannego drzewca i pozwolę mu ją zbadać, żeby sprawdził, czy to prawda.$B$BPrzynieś mi trochę tego szrapnela, żeby gnom mógł powiedzieć mi coś więcej...', 'Przynieś kawałek skorodowanego szrapnela Kaeli Cienistej Włóczni w Górach Szponogłazach.', '', 'Wróć do Kaeli Cienistej Włóczni w Górach Szponogłazach.', '', '', '', '', 0),
(1087, 'koKR', 'Dziedzictwo Cenariusa', 'Nie wyobrażasz sobie, jak bardzo nienawidzę tej nędznej krainy. Pomioty Cenariusa i druidzi kaldorei na szczycie używają swoich żałosnych mocy, by tłumić przepływ magii, nawet tak daleko na południe od swoich żałosnych włości... swoich ukochanych lasów.$b$bObym mogła wrócić do Jaedenaru i rozkoszować się przepływem magii, lecz mój pan nie pozwoli mi wrócić, dopóki nie skończę swojej pracy.$b$bNie wątpię, że kochasz nocne elfy i ich sojuszników równie mało jak ja. Pomóż mi, a oba nasze cele zostaną osiągnięte.', 'Zabij 4 synów Cenariusa, 4 córy Cenariusa i 4 cenariońskich botaników dla Braelyn Ognistej Dłoni w pobliżu Ustronia Słonecznej Skały.', '', 'Wróć do Braelyn Ognistej Dłoni w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(1088, 'koKR', 'Ordanus', 'Myśleli, że zdołają powstrzymać przepływ magii. Mylili się. Myśleli, że zdołają ukryć Ordanusa, ale zdobędę jego głowę!$b$bMagia daje mi prawdziwe widzenie. Tak... oto i on. Skrzyżowanie dróg... Na szczycie wielkiego drzewa w Jesionowej Kniei. Nazwa... Raynewood. Jeden z najstarszych synów boga lasu. Zabrali go ze szczytu, zanim zdążyłam go odnaleźć, ale jego czas się kończy.$b$bPrzynieś mi jego głowę, a podzielę się z tobą potężnym darem.', 'Przynieś głowę Ordanusa Braelyn Ognistej Dłoni w pobliżu Ustronia Słonecznej Skały.', '', 'Wróć do Braelyn Ognistej Dłoni w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(1089, 'koKR', 'Legowisko', 'Druidzi zbudowali Legowisko Szponów na Szczycie Szponogłazów i przechowują w nim wiele potężnych przedmiotów.$b$bWymyślili skomplikowany sposób, by nie wpadły w niepowołane ręce.$b$bNa szczęście udało mi się... wydobyć kilka szczegółów od jednego z nich.$b$bW małej latarni przy wejściu do Legowiska znajdziesz ukryty klucz odźwiernego – dzięki niemu otworzysz skrytki rozmieszczone w Legowisku. Przedmioty z tych skrytek pozwolą ci otworzyć skarbiec druidów, który znajduje się w jednej z centralnych części.', 'Udaj się do Legowiska Szponów na Szczycie Szponogłazów. Za pomocą klucza odźwiernego zdobądź przedmioty ukryte przez druidów. Użyj ich, by otworzyć Skarbiec Legowiska Szponów.', '', 'Odszukaj Skarbiec Legowiska Szponów w Legowisku Szponów w Górach Szponogłazach.', '', '', '', '', 0),
(1090, 'koKR', 'Rozkazy Gerenza', 'Wiesz, kiedyś byłem drugą najważniejszą osobą na tym terenie. Wszystko się zmieniło, gdy przejął go Gerenzo. Zwolnił mojego szefa, Ziza Fizziksa, a mnie zesłał do pracy w kopalni. Ziz kazał mi jednak zostać i zbierać informacje. Jego nowy szef dobrze nam zapłaci, jeśli dowiemy się, co planuje Gerenzo.$b$bW każdym razie wiem tyle, że Gerenzo kazał wydobyć mnóstwo tej złotozielonej rudy. Mogę zdobyć próbkę, którą zaniesiesz Zizowi, ale musisz wypatrywać patroli, kiedy będę ją wydobywał.', 'Odbierz od Piznika tajemniczą rudę, gdy skończy ją wydobywać.', 'Chroń Piznika, gdy wydobywa tajemniczą rudę', 'Porozmawiaj z Piznikiem w Górach Szponogłazach.', '', '', '', '', 0),
(1091, 'koKR', 'Wieści dla Kaeli', '$N, zanieś te listy Kaeli. Na pewno zechce się o tym dowiedzieć. A przynajmniej Strażniczki zechcą.$B$BKoniecznie powiedz jej, jaki odnieśliśmy sukces i że nie udałoby się nam bez odrobiny magii.', 'Zanieś listy spółki Gitgeszeft Kaeli Cienistej Włóczni w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1092, 'koKR', 'Rozkazy Gerenza', 'Chyba też powinienem pomyśleć o tym, żeby się stąd wynieść. Wieść o tym, co tu zaszło, szybko dotrze do szefostwa, a jestem pewien, że nie ucieszyliby się na mój widok.$b$bWymknę się i spotkam z Zizem. Mam nadzieję, że znajdzie mi nową robotę!$b$bSpróbuję trochę tu posprzątać, a ty od razu zanieś próbkę rudy Zizowi. Mówił mi, że rozbije obóz gdzieś po zachodniej stronie Turni Tnącego Wiatru. Powodzenia.', 'Dostarcz niezidentyfikowaną rudę Zizowi Fizziksowi w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1093, 'koKR', 'Superżniwiarz 6000', 'Okropne, co spółka Gitgeszeft tu narobiła, co? Co oni sobie myśleli? Goblińska spółka zatrudnia gnoma!$b$bNa szczęście dla mnie Sputtervalve rozpoznaje geniusza, kiedy go widzi. Zatrudnił mnie zaraz po tym, jak mnie wykopali!$b$bMówi, że zbudowali jakąś ogromną maszynę do wyrębu, a Sput chce, żebym wykradł dla niego jej plany. Niestety Gerenzo – przeklęty gnom – chce mnie zabić, gdy tylko mnie zobaczy... może ty wykradniesz dla mnie te plany? Powinny być u któregoś z ich operatorów.', 'Zdobądź plany Superżniwiarza 6000 dla Ziza Fizziksa w Górach Szponogłazach.', '', 'Wróć do Ziza Fizziksa na Turni Tnącego Wiatru w Górach Szponogłazach.', '', '', '', '', 0),
(1096, 'koKR', 'Gerenzo Wrenchwhistle', 'Spotkałem kiedyś Gerenza i powiem ci, że nie jest miły dla oka. Jego ciało wygląda, jakby gniło, a do tego przyszczepił sobie metal i tryby, a niektóre kończyny zastąpił mechanicznymi.$b$bNa północny wschód stąd, wysoko nad Jeziorem Skalnej Sadzawki, w pobliżu koła wodnego, Gerenzo ma oko na cały teren. Nie ma mowy, żebym się tam przebił, nie mówiąc już o walce z samym Gerenzem... Ale ty wyglądasz, jakby ci się to mogło udać.$b$bJeśli go dla mnie zabijesz, sowicie ci to wynagrodzę!', 'Przynieś mechaniczne ramię Gerenza Wrenchwhistle\'a Zizowi Fizziksowi w Górach Szponogłazach.', '', 'Wróć do Ziza Fizziksa na Turni Tnącego Wiatru w Górach Szponogłazach.', '', '', '', '', 0),
(1152, 'koKR', 'Próba wiedzy', 'Nasz wspólny czas dobiega końca. Mam dużą wiedzę, ale to nie ja przeprowadzam Próbę wiedzy. Są lekcje, które trzeba odebrać, i miejsca, które trzeba odwiedzić, a władzę nad nimi sprawują inni.$B$BJeśli jesteś $ggotów:gotowa;, odszukaj Brauga Mętnego Ducha – to szaman wielkiej mądrości. Podda cię dalszym próbom, więc słuchaj jego słów, $N.$B$BGdy będziesz $ggotów:gotowa;, znajdź tunel łączący Góry Szponogłazy z Jesionową Knieją: Braug mieszka w jego pobliżu. I uważaj, $N, nocne elfy mogą chcieć przeszkodzić ci w próbie.', 'Odszukaj Brauga Mętnego Ducha w pobliżu wejścia na Ścieżkę Głębokiego Szponu w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1154, 'koKR', 'Próba wiedzy', '$GPrzeszedłeś:Przeszłaś; próby Dorna, a teraz chcesz przejść kolejną. Bardzo dobrze. Ale dotąd twoje wyzwania były dziecinne. Łatwo sprawdzić ciało – umysł to zupełnie inna sprawa.$B$BWyjaśnię to prosto: znajdź księgę, którą wskażę, przestudiuj ją i odpowiedz na moje pytanie o jej treść.$B$BJaka to księga, zapewne pytasz? „Dziedzictwo Aspektów”. Znajdziesz ją w najgłębszej części Kurhanu Dor\'Danil w południowej Jesionowej Kniei, strzeżoną przez martwych druidów i ich zabójców.', 'Znajdź „Dziedzictwo Aspektów” i przynieś je Braugowi Mętnemu Duchowi w pobliżu wejścia na Ścieżkę Głębokiego Szponu w Górach Szponogłazach.', '', 'Wróć do Brauga Mętnego Ducha w pobliżu wejścia na Ścieżkę Głębokiego Szponu w Górach Szponogłazach.', '', '', '', '', 0),
(5881, 'koKR', 'Wezwanie rezerw', 'Horda dba o to, by nasze oddziały były wypoczęte... od czasów Wielkiej Wojny dobrze nam się tu, w Kalimdorze, wiedzie.$B$BChcę cię prosić o przysługę. Mam chłopaka imieniem Grish Długi Bieg, który strzeże Wielkiej Windy na południu Pustkowi. Daj mu ten list; dowie się z niego, że wysyłam wojownika z rezerwy, który zluzuje go na posterunku, żeby mógł odwiedzić rodzinę. Prosił o to jakiś czas temu i ucieszy się z tej wiadomości.', 'Maggran chce, żebyś $gdostarczył:dostarczyła; list Grishowi Długiemu Biegowi przy Wielkiej Windzie na Pustkowiach.', '', '', '', '', '', '', 0),
(6282, 'koKR', 'Harpie zagrażają', 'Taureni są dumni z tego, że chronią te ziemie. Z pewnością domyślasz się, czemu niepokoi mnie liczba harpii, które żyją tu, w Górach Szponogłazach.$B$BTo harpie Krwawej Furii odpowiadają za rosnącą liczbę harpii w Kalimdorze; napierają na wszelkie życie i nie pozwalają niewinnym wydostać się poza swoje granice.$B$BMusisz przetrzebić harpie, $N!', 'Maggran Więź Ziemi z Ustronia Słonecznej Skały chce, żebyś $gzabił:zabiła; 7 harpii Krwawej Furii, 7 napastniczek Krwawej Furii, 7 zabójczyń Krwawej Furii i 7 łotrzyc Krwawej Furii.', '', 'Wróć do Maggrana Więzi Ziemi w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6283, 'koKR', 'Ród Krwawej Furii', 'Ograniczenie liczby harpii Krwawej Furii nie wystarczy. Jedynym prawdziwym lekarstwem na tę zarazę będzie zabicie ich przywódczyni, Rozpruwaczki Krwawej Furii!$B$BDla tych plugawych stworzeń jest niemal królową. Zabij ją, a ich liczba z pewnością zmaleje.$B$BWróć do Zwęglonej Doliny, a znajdziesz ją na zachodnich wzgórzach. Niełatwo będzie ją pokonać, ale nagroda będzie wielka.', 'Maggran z Ustronia Słonecznej Skały chce, żebyś $gzabił:zabiła; Rozpruwaczkę Krwawej Furii i $gprzyniósł:przyniosła; jej szczątki na dowód.', '', 'Wróć do Maggrana Więzi Ziemi w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6284, 'koKR', 'Arachnofobia', 'Ostrzeżenie: wchodzisz do Kanionu Sishir na zachód stąd na własne ryzyko.$B$BBesseleth i jej ośmionogie dzieci lasu uczyniły z tego kanionu swoje opięte pajęczyną leże.$B$BMaggran Więź Ziemi z Ustronia Słonecznej Skały wyznaczył nagrodę za Besseleth. Zabij ją i przynieś Maggranowi dowód; otrzymasz od niego nagrodę za pozbycie się tego ośmionogiego zagrożenia.', 'Zabij Besseleth i przynieś kieł Besseleth Maggranowi do Ustronia Słonecznej Skały.', '', 'Wróć do Maggrana Więzi Ziemi w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6301, 'koKR', 'Cykl odrodzenia', 'Przemysłowa chciwość i nieustanna wojna zrujnowały ziemie Szponogłazów. Tylko błogosławieństwa Matki Ziemi mogą uleczyć takie rany.$B$B$N, potrzebuję, żebyś $godszukał:odszukała; szczególnego nasiona – nasiona Gai. Rosną tylko tutaj, w Górach Szponogłazach, na północ od Ustronia Słonecznej Skały, nad Jeziorem Mirkfallon, przy samym brzegu.$B$BGdy przyniesiesz mi nasiona, nasycę je szamańską mocą, by przyspieszyć ich wzrost.', 'Tammra Wietrzne Pole z Ustronia Słonecznej Skały chce, żebyś $gzebrał:zebrała; 10 nasion Gai.', '', 'Wróć do Tammry Wietrzne Pole w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6381, 'koKR', 'Nowe życie', 'Jak $gwidziałeś:widziałaś;, choć ziemia cierpi, cykl życia ma wielką moc. Teraz musimy zrobić, co do nas należy, i mu pomóc. Musisz posadzić te nasiona w samym sercu zniszczeń, na zachodzie, w Zwęglonej Dolinie. Uważaj, bo harpie i rozwścieczone żywiołaki ognia wciąż nękają tę pokaleczoną ziemię.$B$B$N, weź te zaczarowane nasiona Gai i posadź je w żyznych kopcach ziemi. Cykl życia musi trwać!', 'Posadź 10 nasion Gai w kopcach ziemi Gai, a następnie zwróć pozostałe zaczarowane nasiona Gai Tammrze w Ustroniu Słonecznej Skały.', '', 'Wróć do Tammry Wietrzne Pole w Ustroniu Słonecznej Skały w Górach Szponogłazach.', 'Posadzone nasiona Gai', '', '', '', 0),
(6393, 'koKR', 'Wojna żywiołów', 'Trybunał Przypływów przysłał mnie tu na wojnę z żywiołakami ognia w Górach Szponogłazach. Neptulon Łowca Przypływów, władca wszystkich żywiołaków wody, osobiście pragnie ujrzeć, jak nasi ogniści kuzyni zostają zgaszeni.$B$B$N, możesz pomóc mi zyskać przychylność Trybunału, niszcząc żywiołaki ognia w Zwęglonej Dolinie. Zniszczone żywiołaki ognia pozostawiają po sobie inkendryty. Przynieś mi je, a zostaniesz $gnagrodzony:nagrodzona;.', 'Przynieś 10 inkendrytów Tsunamanowi w Ustroniu Słonecznej Skały.', '', 'Wróć do Tsunamana w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6421, 'koKR', 'Parów Osuwiska', 'Coś tu, w Górach Szponogłazach, jest nie tak. Czujesz to napięcie w powietrzu, $N?$B$BNa południowy wschód stąd, w Parowie Osuwiska, jest głęboka jaskinia. Koboldy gorączkowo wydobywają tam rzadki kryształ zwany rezonitem. Przynieś mi kilka próbek, żebym mógł zrozumieć, co się dzieje w tej jaskini. Musisz też zbadać, jak głęboko sięga.$B$BIdź, $N, muszę koniecznie wiedzieć, jakie zło czai się pod tymi górami.', 'Zbadaj głębiny jaskini w Parowie Osuwiska i przynieś 10 kryształów rezonitu Mor\'rogalowi do Ustronia Słonecznej Skały, by mógł je zbadać.', 'Zbadaj jaskinię w Parowie Osuwiska', 'Wróć do Mor\'rogala w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6461, 'koKR', 'Krwiopijcy', 'My, trolle z Malaka\'jin, dobrze żyjemy z tej ziemi; Góry Szponogłazy dają nam świetne łowy.$B$BOstatnio jednak przyciągamy nie tych gości na kolację... pająki z tych gór napadają nocą na nasze obozy, żeby ukraść nam zdobycz.$B$BJeśli pomożesz nam wybić te ohydne bestie, my w Malaka\'jin będziemy twoimi dłużnikami. Pająki są wszędzie w Górach Szponogłazach – idź stąd na północ, to zobaczysz, o czym mówię.', 'Xen\'Zilla z Malaka\'jin chce, żebyś $gzabił:zabiła; 10 pełzaczy z Głębomchu i 7 jadoplujów z Głębomchu.', '', 'Wróć do Xen\'Zilli w Malaka\'jin w Górach Szponogłazach.', '', '', '', '', 0),
(6481, 'koKR', 'Ziemny powstaje', '$GOdkryłeś:Odkryłaś; mroczne zagrożenie dla tej ziemi, $N. Baryłka z rezonitem, którą $gznalazłeś:znalazłaś; w tej jaskini, skrywa uśpionego ziemnego imieniem Goggeroc.$B$BSwoimi szamańskimi mocami zmieniłem skład kryształów rezonitu, które $gzebrałeś:zebrałaś;. Weź zaklęty kryształ rezonitu i roztrzaskaj nim baryłkę z rezonitem, w której spoczywa ziemny.$B$BPo przebudzeniu Goggeroc będzie osłabiony... Zabij go, $N!', 'Otwórz baryłkę z rezonitem zaklętym kryształem rezonitu, a następnie zabij Goggeroca. Wróć do Mor\'rogala z wieściami i zaklętym kryształem rezonitu.', '', 'Wróć do Mor\'rogala w Ustroniu Słonecznej Skały w Górach Szponogłazach.', '', '', '', '', 0),
(6627, 'koKR', 'Próba wiedzy', '$GPrzyniosłeś:Przyniosłaś; mi księgę, a teraz czas na twoje pytanie. Jesteś $ggotów:gotowa;?$B$BCzas nie gra roli, $N, więc nie czuj presji. Możesz się namyślać, jak długo zechcesz.', 'Poprawnie odpowiedz na pytanie Brauga Mętnego Ducha, a następnie porozmawiaj z nim ponownie. Będzie czekał w Górach Szponogłazach, aż będziesz $ggotów:gotowa;.', 'Poprawnie odpowiedz na pytanie Brauga Mętnego Ducha', 'Wróć do Brauga Mętnego Ducha w Górach Szponogłazach.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(1057, 'koKR', 'Teraz, gdy harpie Krwawej Furii poniosły tak wielkie straty, może wreszcie zacznie się prawdziwa praca nad odnową tej ziemi...', 0),
(1058, 'koKR', 'Och, jak szczęśliwe będą te małe leśne nimfy! Dzięki tej specjalnej miksturze poczują się jak u siebie!', 0),
(1059, 'koKR', 'Opiekun Albagorm postąpił mądrze, wysyłając cię z takim pośpiechem.$B$BZobaczmy, czy zdołamy wezwać pomoc z wielkiego lasu, by dotarła do Zwęglonej Doliny, zanim będzie za późno.', 0),
(1071, 'koKR', 'Wielkie dzięki za pomoc, $N. Właściwie wracasz w samą porę.$B$BChyba mam idealny plan. Materiały wybuchowe. Nie, to nie jest plan, ale to część planu.$B$BWidzisz, używam silnych materiałów wybuchowych – spokojnie, nie są tak niebezpieczne, jak wszyscy myślą – żeby trochę odstraszyć gobliny. Kilkoma dobrze rozmieszczonymi wybuchami na krawędziach gór całkiem nieźle je zaganiam, ale od kilku dni brakuje mi zapasów.', 0),
(1079, 'koKR', 'Naprawdę niesamowite! To potężny cios dla spółki Gitgeszeft.$B$BZnajdziemy słabe punkty ich maszyn, a ich projekty wykorzystamy we własnych dziełach. Doprawdy wspaniały dzień.', 0),
(1080, 'koKR', 'Niewiarygodne, $N! Kaela i Strażniczki będą zachwycone. Z twoimi umiejętnościami i moimi wynalazkami nikt nas nie powstrzyma.', 0),
(1083, 'koKR', 'Szczątki naszego wroga... twoja siła dobrze nam służy, $N. Dziękuję.', 0),
(1084, 'koKR', 'Dziękuję, $N.$B$BTo z nawiązką wystarczy, by Gaxim ustalił, jak zepsuto drzewce. Zaraz mu to przekażę.', 0),
(1087, 'koKR', 'Już to czuję... tak... cóż za słodka moc... rwący potok. Kaldorei głupio czynią, wzgardziwszy darami tego świata i odrzucając magię, która śpiewnie płynie w żyłach.$b$bJakąż bladą parodią jest życie bez jej palących objęć!', 0),
(1088, 'koKR', 'Znałam kiedyś Ordanusa, dawno temu. Miał w sobie arogancję swojego rodzaju, stawiał się wyżej nawet od Wysoko Urodzonych.$b$bTeraz jego głowa nie wznosi się już tak wysoko, prawda, $N?$b$bObiecałam ci nagrodę i ją otrzymasz. Podejdź.', 0),
(1089, 'koKR', 'Gdy trzy klucze wsuwają się w pasujące do nich otwory, pośród jarzącego się światła pojawia się kilka przedmiotów.', 0),
(1090, 'koKR', 'Dzięki, $N. Przez chwilę wyglądało to nieciekawie i pewnie ściągnęliśmy na siebie o wiele za dużo uwagi.$b$bNajważniejsze jednak, że mamy próbkę rudy i powinniśmy jak najszybciej dostarczyć ją Zizowi.', 0),
(1091, 'koKR', 'To doprawdy interesujące.$B$BTy i Gaxim spisaliście się bardzo dobrze, $N. Dziękuję.', 0),
(1092, 'koKR', 'Aaa, wiedziałem, że dobrze zrobiłem, każąc Piznikowi zostać. Jestem pewien, że inżynierowie w Undermine z wielkim zainteresowaniem się temu przyjrzą...$b$bOczywiście zatrzymam sobie mały kawałek, ale czego oczy nie widzą, tego sercu nie żal, prawda?', 0),
(1093, 'koKR', 'Hej, czy to jest to, o czym myślę? Świetnie!$b$bNo to zobaczmy. Ech... jak ja mam to zrozumieć... nie pojmę, jak myślą gnomy. Powiem ci, dziwię się, że zdołały wymyślić koło, a co dopiero te latające maszyny, które tak lubią.', 0),
(1096, 'koKR', 'Popatrz tylko na to... coś takiego mógł wymyślić tylko gnom. Nie rozumiem, po co odcinać sobie rękę i zastępować ją czymś takim, skoro można zachować obie i dodać trzecią!$b$bMówię ci, te gnomy...$b$bPrzynajmniej Gerenzo jest wyłączony z gry. Mam nadzieję, że to wystarczy za dowód i Sputtervalve przydzieli mnie do jednego z warsztatów Związku Majsterkowiczów w Gadżetonie, a może nawet w Undermine.', 0),
(1152, 'koKR', 'Dni i noce na całym świecie stają się coraz zimniejsze, gdy gobliny pustoszą ziemię, a nocne elfy wytykają palcami młodsze rasy. Nie tylko Porzuceni i orkowie ponoszą winę za niedolę w całym Kalimdorze i Lordaeronie. Wiele rozumnych ras przyczyniło się do cierpienia świata. Dorn o tym wie i przysłał cię do mnie, bo $gpokazałeś:pokazałaś;, że masz przymioty potrzebne, by i ty to pojąć.$b$bOto stoisz przed Braugiem.', 0),
(1154, 'koKR', 'To księga, którą wskazałem. Jest więc nadzieja, że poprawnie odpowiesz na moje pytanie... chyba że $gzapomniałeś:zapomniałaś; przestudiować jej treść.$b$bGdy będziesz $ggotów:gotowa;, porozmawiaj ze mną ponownie, a zadam ci pytanie.', 0),
(5881, 'koKR', 'Wspaniała wiadomość! Za długo już tu siedzę i pilnuję tego kawału drewna. Teraz mogę spędzić trochę czasu z rodziną... Hurra!', 0),
(6282, 'koKR', 'Wyśmienite wieści! Opowiedz mi jeszcze raz, jak $gzasiałeś:zasiałaś; strach w zimnych sercach tych podłych harpii. Harpie Krwawej Furii otrzymały poważny cios!', 0),
(6283, 'koKR', 'Już czuję, jak opuszcza mnie gniew. Co ja teraz zrobię z czasem? Świadomość, że zło krąży blisko mojej ziemi, nie dawała moim myślom spocząć, a teraz ucichły. Może to dobrze... może teraz mogę skupić się na dobru, jak powinien każdy tauren.$b$bPrzyjmij to w nagrodę za trud.', 0),
(6284, 'koKR', 'Udane łowy, $N! Besseleth to stara drapieżczyni w tych stronach... nie będę za nią tęsknił. Weź tę nagrodę jako wyraz uznania dla $gobrońcy:obrończyni; lasu.$b$b<Maggran pociera ranę zadaną przez Besseleth.>$b$bMoże teraz wielu więcej podróżnych przybędzie do Ustronia Słonecznej Skały, nie bojąc się tego, co czai się w ciemności.', 0),
(6301, 'koKR', 'Ach, $N, masz nasiona Gai. Patrz, jak błogosławieństwo Matki Ziemi sprawia, że nawet te małe ziarenka życia rozkwitają i bujnie rosną.$b$b<Tammra zaczyna intonować pieśń.>', 0),
(6381, 'koKR', 'To wielkie zwycięstwo dla tej ziemi. Z czasem nadejdą i inne zmiany: spółka Gitgeszeft spakuje swoje piły tarczowe i siekiery, rozwścieczone duchy ognia się uspokoją, a harpie zostaną wyparte przez samą ziemię.$b$bDopiero wtedy, $N, w Górach Szponogłazach naprawdę zapanuje pokój.$b$bDobrze się $gspisałeś:spisałaś; – weź jeden z tych przedmiotów w podzięce za nowe życie, które dziś tu $gstworzyłeś:stworzyłaś;.', 0),
(6393, 'koKR', 'Duchy wody we mnie aż kipią z podniecenia. $N, dzięki tobie mogę donieść Trybunałowi Przypływów o wspaniałym zwycięstwie.$b$b', 0),
(6421, 'koKR', 'Ach... Tak! To jest to; kryształy rezonitu noszą ślad magii ziemnych. Koboldy musiały dokopać się głęboko i odsłonić jednego z ziemnych.$b$bLegenda głosi, że ziemni to istoty stworzone przez tytanów. Posłużyli do ukształtowania ziemi, po której stąpamy. To zagrożenie, którego z pewnością nie można zignorować.$b$b<Mor\'rogal kręci głową.>$b$bMoże zdołam zaczarować te próbki, by użyć ich przeciwko spiskowi koboldów.', 0),
(6461, 'koKR', 'Super, mon! Dobre wieści, może dziś wieczorem będzie mniej nieproszonych gości na kolacji.$b$bWielkie dzięki, $N. Na zawsze jesteśmy twoimi dłużnikami.', 0),
(6481, 'koKR', 'Przynosisz dobre wieści, $N! Lękam się myśleć, co ziemny mógłby oznaczać dla Kalimdoru.$b$bZabicie Goggeroca było zadaniem na miarę prawdziwego bohatera. Dobrze się $gspisałeś:spisałaś; – całe Góry Szponogłazy i cały Kalimdor są twoimi dłużnikami, $gszlachetny:szlachetna; $N.$b$bPrzyjmij to w nagrodę, $gczcigodny bohaterze:czcigodna bohaterko;.', 0),
(6627, 'koKR', 'Dobra robota, $N. $GPrzestudiowałeś:Przestudiowałaś; tekst, który ci wskazałem, i $gprzeszedłeś:przeszłaś; kolejną z naszych prób.', 0),
(11780, 'koKR', 'Zbezcześć wielkie ognisko Hordy w Górach Szponogłazach!', 0),
(11856, 'koKR', 'Uczcij płomień Gór Szponogłazów!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(1057, 'koKR', 'Wiele pracy trzeba jeszcze wykonać, zanim Zwęglona Dolina znów stanie się bujnym lasem, jakim niegdyś była.$B$BOczyść okolicę z tych plugawych szkodników, $N! Dopiero wtedy będziemy mogli odzyskać to, co należy do natury.', 0),
(1058, 'koKR', 'Popatrz na naszych biednych elfich przyjaciół. Pozamykani w klatkach, bez lasu, w którym mogliby hasać!$b$bNo to jak, $gznalazłeś:znalazłaś; dla mnie trochę żywicy? A wąsy zmierzchowych biegaczy? Nie masz przypadkiem przy sobie tej łuski baśniowego smoka?$b$bI oczy! Potrzebuję mnóstwa oczu! Porządnego, zajadłego wywaru z leśnej magii nie da się przyrządzić bez solidnej porcji oczu!', 0),
(1071, 'koKR', 'Jak ci idzie walka, $N?', 0),
(1079, 'koKR', '$GZdobyłeś:Zdobyłaś; plany, $N?', 0),
(1080, 'koKR', 'Jak poszło, $N?', 0),
(1083, 'koKR', 'Gdy pierwszy raz ujrzałam Zwęgloną Dolinę, niemal się rozpłakałam, $N.', 0),
(1084, 'koKR', 'Mam przeczucie, że Gaxim znajdzie zastosowanie dla tego szrapnela, niezależnie od tego, jak spółka Gitgeszeft używała go wcześniej.', 0),
(1087, 'koKR', 'Czerpanie magii w tym miejscu przypomina czerpanie wody ze studni dziurawym wiadrem.', 0),
(1088, 'koKR', 'Gdy mój pan posłał mnie na szczyt Szponogłazów, sądziłam, że wystarczy zetrzeć z powierzchni ziemi nocne elfy, które pełzały po świętych ruinach naszej starożytnej świątyni Aszary, bezczeszcząc jej świętość swoim dotykiem... lecz Ordanus wymknął mi się z rąk.', 0),
(1089, 'koKR', 'W kamieniu wyryto trzy dziurki od klucza.', 0),
(1091, 'koKR', 'Tak, $N? W czym mogę ci pomóc?', 0),
(1092, 'koKR', 'W czym mogę pomóc?', 0),
(1093, 'koKR', '$GZnalazłeś:Znalazłaś; te plany? Nie mogę się doczekać, żeby zaimponować nowemu szefowi. Mam nadzieję, że kiedy przekona się o mojej lojalności – no, na tyle, na ile da się go przekonać... słowo goblina, wiesz? – bez obaw zacznie korzystać z mojego nader imponującego geniuszu.', 0),
(1096, 'koKR', 'Sputtervalve będzie chciał jakiegoś dowodu, że Gerenzo nie żyje. Myślę, że jego mechaniczne ramię wystarczy.', 0),
(1154, 'koKR', 'Przynieś mi księgę, gdy już ją przestudiujesz. Nie zadam ci pytania, dopóki mi jej nie oddasz.', 0),
(5881, 'koKR', 'Masz wieści od Maggrana Więzi Ziemi?', 0),
(6282, 'koKR', 'Nie trać czujności w Zwęglonej Dolinie; na tych wzgórzach żyje wiele złych istot. Bądź $gsilny:silna;, $N, a pokonasz to zagrożenie dla naszego ludu. Idź teraz i uderz mocno – niech nasze dzieci nigdy nie poznają zła, które tu było.', 0),
(6283, 'koKR', 'Rozpruwaczka Krwawej Furii to paskudna bestia! Znajdziesz ją wzdłuż zachodniej linii wzgórz w Zwęglonej Dolinie.$b$bBez niej harpie Krwawej Furii będą bezradne... na pewno zdołamy pokonać je na zawsze!', 0),
(6284, 'koKR', 'Besseleth to bezlitosna drapieżczyni... boję się o tych, którzy nocą wędrują Ścieżką Sieciowijów. To wtedy ona i jej dzieci polują na niewinnych podróżnych. Sam padłem ofiarą jej dwustopowego kła śmierci, ale na szczęście zdołałem ją odeprzeć i ujść w bezpieczne miejsce. Oddałbym wszystko, by zobaczyć tego potwora martwym.', 0),
(6301, 'koKR', 'Nieustanne zniszczenia, jakie niosą wojna i ci, którzy szukają zysku z drewna, głęboko mnie bolą. By wesprzeć cykl odrodzenia i odnowić ziemię, potrzebuję nasion Gai. Masz je, $N?', 0),
(6381, 'koKR', 'Nasiona, które sadzisz, są silne, opierają się zepsuciu i torują drogę innemu życiu. Będą rosły i rosły, najpierw powstrzymując zepsucie i lecząc pokaleczoną ziemię, a pewnego dnia znów zmienią Góry Szponogłazy w bujny las.$b$b$GPosadziłeś:Posadziłaś; już wszystkie nasiona Gai?', 0),
(6393, 'koKR', 'Trybunał Przypływów się niecierpliwi. Pragnie zakończyć wojnę, która od eonów szaleje we wszystkich wymiarach. Moi bracia z niecierpliwością czekają na wieść o wspaniałym zwycięstwie nad znienawidzonymi żywiołakami ognia. Masz inkendryty, których potrzebuję?', 0),
(6421, 'koKR', 'Jakie wieści przynosisz z Parowu Osuwiska? Pamiętam jakąś legendę o rezonicie... mam ją na końcu języka, tylko nie mogę jej uchwycić. Może gdy się dowiemy, co kryje się na dnie jaskini, wyjdą na jaw ich podstępne zamiary.', 0),
(6461, 'koKR', 'Hej, mon, $gzabiłeś:zabiłaś; te włochate krwiopijce? Ja tu w Szponogłazach nikogo się nie boję, ale nocą nie chodzę na spacery... wiesz, o co chodzi, mon!$b$bDopóki nie ląduję na ich talerzu, wszystko gra.$b$bPowodzenia, $N!', 0),
(6481, 'koKR', 'Obawiam się, że jeśli natychmiast nie pozbędziemy się tego zagrożenia, całe Góry Szponogłazy przepadną. Potędze ziemnego nic nie dorówna. Po przebudzeniu Goggeroc będzie osłabiony długim snem – to okazja, którą musisz wykorzystać... idź już, $N!', 0),
(6627, 'koKR', 'Życie jest pełne pytań, $N. Nigdy nie odpowiesz na wszystkie, ale z czasem i nauką może staniesz się nieco $gmądrzejszy:mądrzejsza;.', 0),
(9024, 'koKR', 'W czym mogę pomóc?', 0);
