(3411, 'koKR', 'Denni\'ka', 'Rzeźniczka', 0),
(3988, 'koKR', 'Operator spółki Gitgeszeft', '', 0),
(3991, 'koKR', 'Karczownik spółki Gitgeszeft', '', 0),
(3992, 'koKR', 'Inżynier spółki Gitgeszeft', '', 0),
(3993, 'koKR', 'Mechanik spółki Gitgeszeft', '', 0),
(3999, 'koKR', 'Kopacz Tnącego Wiatru', '', 0),
(4003, 'koKR', 'Geomanta Tnącego Wiatru', '', 0),
(4004, 'koKR', 'Zwierzchnik Tnącego Wiatru', '', 0),
(4005, 'koKR', 'Pełzacz z Głębomchu', '', 0),
(4006, 'koKR', 'Prządka z Głębomchu', '', 0),
(4007, 'koKR', 'Jadopluj z Głębomchu', '', 0),
(4008, 'koKR', 'Klifowy burzyciel', '', 0),
(4009, 'koKR', 'Rozwścieczony klifowy burzyciel', '', 0),
(4011, 'koKR', 'Młoda dumnoskrzydła wiwerna', '', 0),
(4012, 'koKR', 'Dumnoskrzydła wiwerna', '', 0),
(4013, 'koKR', 'Dumnoskrzydły łowca nieba', '', 0),
(4014, 'koKR', 'Dumnoskrzydła towarzyszka', '', 0),
