INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2491, 'koKR', 'Grishu!$B$BTwoja prośba o urlop została przyjęta. Wysyłam taureńskiego wojownika z rezerwy, który przejmie twój posterunek, abyś mógł spędzić trochę czasu z rodziną. Zgłoś się z powrotem za tydzień!$B$B– Maggran Więź Ziemi', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1427, 'koKR', 'Dobra, pilnuj moich pleców, a ja wydobędę dla ciebie trochę tej rudy.', '', 0),
(1430, 'koKR', 'Chyba te odgłosy dochodziły stąd. Lepiej to sprawdźmy.', '', 0),
(1431, 'koKR', 'Uwaga! Chyba nadchodzi ich więcej!', '', 0),
(1432, 'koKR', 'Jeszcze chwilka, już prawie mam!', '', 0),
(1433, 'koKR', 'Co tu się dzieje? Piznik! Wiedziałem, że nie powinniśmy pozwolić ci tu zostać!', '', 0),
(1434, 'koKR', 'Proszę, mam!', '', 0),
(7937, 'koKR', 'Czy $gprzybyłeś:przybyłaś;, by szukać wiedzy Hgartha?', '', 0),
(8089, 'koKR', 'Obawiam się, że łagodność i pokora już mnie opuściły. Wiek i niezliczone bitwy zahartowały moją skórę i duszę. Może dlatego Kairn przydzielił mnie do Ustronia Słonecznej Skały... łagodne wiatry i ciepłe słońce koją ból.', '', 0),
(8330, 'koKR', 'W Górach Szponogłazach jest wiele niebezpiecznych jaskiń. Ich eksploracja może przynieść wiele przygód tym, którzy gotowi są zaryzykować życie dla chwały.$B$B$N, być może szukasz bogactw, które zdobędziesz tylko, idąc za głosem serca i duszy.', '', 0),
(66076, 'koKR', 'Czego chcesz?', 'Czego chcesz?', 0);
